 function characterize(page){const groups=['Beneficiario','Estudiante','Cargo del colaborador'];const rows=page.rows||[],h=['Categoría','Cantidad','%'];const r=groups.map(g=>rows.filter(x=>x[0]===g).map(x=>x.slice(1)));const w=(CW-23)/2;const startY=y;let a=panelTable(h,r[0],L,y,w,B-120,'Tipo de beneficiario',[3,1.1,1]);let b=panelTable(h,r[1],L,a.end+24,w,B-40,'Antiguos vs. nuevos',[3,1.1,1]);let c=panelTable(h,r[2],L+w+23,startY,w,B-30,'Distribución por cargos',[3.7,1,1],12.5);y=Math.max(b.end,c.end)+18;for(const [i,rem] of [a.remaining,b.remaining,c.remaining].entries())if(rem.length){continuation(page);p.txt(['Tipo de beneficiario','Antiguos vs. nuevos','Distribución por cargos'][i],L,y,CW,18,BLACK,true);y+=30;tableFlow(page,h,rem,[4,1,1]);}note(page,page.note);}
 function motivation(page){const items=page.bars||[];if(!items.length){note(page,page.note||'Sin respuestas válidas.');return;}const total=items.reduce((a,b)=>a+Number(b[1]||0),0);const rows=items.map(b=>[b[0],b[1],clean(b[2]??'').split(' · ').at(-1)||'N/D']);const left=580,right=CW-left-18;const res=panelTable(['Aspecto','Respuestas','%'],rows,L,y+12,left,B-50,'Aspectos valorados por los participantes',[3.4,1.05,0.85],14);const first=items[0],top=items.reduce((a,b)=>Number(b[1])>Number(a[1])?b:a,first);const pc=total?`${(100*Number(top[1])/total).toLocaleString('es-CO',{maximumFractionDigits:1})}%`:'N/D';let cardH=340;callout(L+left+18,y,right,cardH,'ASPECTO MÁS VALORADO',pc,top[0]);y=Math.max(y+cardH,res.end)+20;if(res.remaining.length){continuation(page);tableFlow(page,['Aspecto','Respuestas','%'],res.remaining,[3,1,1]);}note(page,page.note);}
 function funnel(page){const b=page.bars||[];if(!b.length)return;const ww=420,other=CW-ww-20,top=y;let cy=y+12;const max=Math.max(1,Number(b[0]?.[1])||1);b.forEach((v,i)=>{const w=Math.max(ww*.56,ww*(1-i*.13)),x=L+(ww-w)/2;p.rect(x,cy,w,66,i===0?Y:i===b.length-1?BLACK:PALE);const col=i===b.length-1?WHITE:BLACK;p.txt(String(v[1]),x+10,cy+7,w-20,24,col,true,'center');p.txt(v[0],x+12,cy+36,w-24,12,col,true,'center');cy+=77;});const right=panelTable(page.headers||['Estado','Cantidad'],page.rows||[],L+ww+20,top,other,B-32,page.rightTitle||'Novedades de la convocatoria',[3,1],12.5);y=Math.max(cy,right.end)+12;if(right.remaining.length){continuation(page);tableFlow(page,page.headers,right.remaining,[3,1]);}note(page,page.note);}
