function hexRGB(s){return [0,2,4].map(i=>(parseInt(s.slice(i,i+2),16)/255).toFixed(4)).join(' ')}
const cp={'€':128,'‘':145,'’':146,'“':147,'”':148,'–':150,'—':151,'…':133,'•':149,'−':45,'→':62,'⚠':63};
function pdfText(s){return '<'+Buffer.from([...clean(s)].map(c=>cp[c]??(c.charCodeAt(0)<256?c.charCodeAt(0):63))).toString('hex')+'>';}
function pdf(pages){const image=Buffer.from(LOGO,'base64');const acc=['','<< /Type /Catalog /Pages 2 0 R >>','', '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>',Buffer.concat([Buffer.from(`<< /Type /XObject /Subtype /Image /Width 528 /Height 106 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${image.length} >>\nstream\n`),image,Buffer.from('\nendstream')])];// Imagen del símbolo a-color (archivo fuente assets/a-color.png) sobre fondo amarillo.
 acc.push(Buffer.concat([Buffer.from(`<< /Type /XObject /Subtype /Image /Width 449 /Height 550 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${Buffer.from(MARK_JPEG,'base64').length} >>\nstream\n`),Buffer.from(MARK_JPEG,'base64'),Buffer.from('\nendstream')]));
 const kids=[];function op(o){if(o.t==='r'){const r=`${o.x} ${H-o.y-o.h} ${o.w} ${o.h} re`;return `${hexRGB(o.fill)} rg ${r} f${o.stroke?`\n${hexRGB(o.stroke)} RG .7 w ${r} S`:''}`;}if(o.t==='i')return `q ${o.w} 0 0 ${o.h} ${o.x} ${H-o.y-o.h} cm /Logo Do Q`;if(o.t==='a')return `q ${o.w} 0 0 ${o.h} ${o.x} ${H-o.y-o.h} cm /Mark Do Q`;if(o.t==='e'){const cx=o.x+o.w/2,cy=H-o.y-o.h/2,rx=o.w/2,ry=o.h/2,k=.55228475;return `${hexRGB(o.stroke)} RG 2 w ${cx+rx} ${cy} m ${cx+rx} ${cy+k*ry} ${cx+k*rx} ${cy+ry} ${cx} ${cy+ry} c ${cx-k*rx} ${cy+ry} ${cx-rx} ${cy+k*ry} ${cx-rx} ${cy} c ${cx-rx} ${cy-k*ry} ${cx-k*rx} ${cy-ry} ${cx} ${cy-ry} c ${cx+k*rx} ${cy-ry} ${cx+rx} ${cy-k*ry} ${cx+rx} ${cy} c S`;}return `BT /F${o.bold?2:1} ${o.sz} Tf ${hexRGB(o.color)} rg 1 0 0 1 ${o.x} ${H-o.y-o.sz*.86} Tm ${pdfText(o.s)} Tj ET`;}
 for(const a of pages){const id=acc.length;kids.push(id+' 0 R');const ops=a.map(op).join('\n');acc.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${W} ${H}] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> /XObject << /Logo 5 0 R /Mark 6 0 R >> >> /Contents ${id+1} 0 R >>`,`<< /Length ${Buffer.byteLength(ops)} >>\nstream\n${ops}\nendstream`);}acc[2]=`<< /Type /Pages /Kids [${kids.join(' ')}] /Count ${kids.length} >>`;const chunks=[Buffer.from('%PDF-1.4\n')],offsets=[0];let pos=chunks[0].length;for(let i=1;i<acc.length;i++){offsets.push(pos);const part=Buffer.concat([Buffer.from(`${i} 0 obj\n`),Buffer.isBuffer(acc[i])?acc[i]:Buffer.from(acc[i]),Buffer.from('\nendobj\n')]);chunks.push(part);pos+=part.length;}chunks.push(Buffer.from('xref\n0 '+acc.length+'\n0000000000 65535 f \n'+offsets.slice(1).map(n=>String(n).padStart(10,'0')+' 00000 n \n').join('')+`trailer\n<< /Size ${acc.length} /Root 1 0 R >>\nstartxref\n${pos}\n%%EOF\n`));return Buffer.concat(chunks);}
async function exportReport(payload,format){if(!payload?.pages?.length||payload.pages.length>250)throw Error('Informe vacío o demasiado extenso');const pages=layout(payload);if(pages.length>350)throw Error('Informe demasiado extenso; descarga por grupo');let buf;if(format==='pdf')buf=pdf(pages);else{const pptx=new PptxGenJS();pptx.defineLayout({name:'EDUCAMAS',width:10,height:7.5});pptx.layout='EDUCAMAS';pptx.author='Educamás';pptx.title=payload.name;for(const a of pages){const slide=pptx.addSlide();for(const o of a){const geom={x:o.x/96,y:o.y/96,w:o.w/96,h:o.h/96};if(o.t==='r'){slide.addShape(pptx.ShapeType.rect,{...geom,line:{color:o.stroke||o.fill,transparency:o.stroke?0:100,width:.5},fill:{color:o.fill}});}else if(o.t==='e'){slide.addShape(pptx.ShapeType.ellipse,{...geom,line:{color:o.stroke,width:1.5},fill:{color:Y,transparency:100}});}else if(o.t==='i'){slide.addImage({data:'image/jpeg;base64,'+LOGO,...geom});}else if(o.t==='a'){slide.addImage({data:'image/png;base64,'+MARK_PNG,...geom});}else slide.addText(o.s,{x:o.x/96,y:o.y/96,w:Math.min(W-o.x,o.w)/96,h:o.sz*1.24/96,fontFace:'Arial',fontSize:o.sz*.75,color:o.color,bold:o.bold,margin:0,breakLine:false,vertAlign:'top',fit:'shrink'});}}buf=Buffer.from(await pptx.write({outputType:'nodebuffer',compression:true}));}const name='Educamas_2027-1_'+clean(payload.name).replace(/[^\p{L}\p{N}_-]+/gu,'_').slice(0,100)+'.'+format;return {name,mime:format==='pdf'?'application/pdf':'application/vnd.openxmlformats-officedocument.presentationml.presentation',base64:buf.toString('base64')};}
module.exports={exportReport,layout};
